import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        boolean[] stock = new boolean[n + 2];
        int next = 1; // smallest volume not bought yet
        StringBuilder sb = new StringBuilder();
        for (int day = 0; day < n; day++) {
            stock[(int) nextLong()] = true;
            int start = next;
            while (next <= n && stock[next]) next++;
            if (start == next) sb.append("-1");
            for (int x = start; x < next; x++) {
                if (x > start) sb.append(' ');
                sb.append(x);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	stock := make([]bool, n+2)
	next := 1 // smallest volume not bought yet
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for day := 0; day < n; day++ {
		stock[nextInt()] = true
		start := next
		for next <= n && stock[next] {
			next++
		}
		if start == next {
			w.WriteString("-1")
		}
		for x := start; x < next; x++ {
			if x > start {
				w.WriteByte(' ')
			}
			w.WriteString(strconv.Itoa(x))
		}
		w.WriteByte('\n')
	}
}
